    used_diff = [False] * (m+1)
    def bt(pos):
        if pos == 9:
            return True
        for val in range(m+1):
            if used_label[val]:
                continue
            # collect new diffs
            new_diffs = []
            conflict = False
            seen_in_new = set()
            for u, v in edges:
                if u == pos:
                    other = v
                elif v == pos:
                    other = u
                else:
                    continue
                if other < pos:  # already assigned
                    if labels[other] is None:
                        print("Error")
                        continue
                    diff = abs(val - labels[other])
                    if diff == 0 or diff > m or used_diff[diff] or diff in seen_in_new:
                        conflict = True
                        break
                    seen_in_new.add(diff)
                    new_diffs.append(diff)
            if conflict:
                continue
            # assign
            labels[pos] = val
            used_label[val] = True
            for d in new_diffs:
                used_diff[d] = True
            if bt(pos + 1):
                return True
            # backtrack
            labels[pos] = None
            used_label[val] = False
            for d in new_diffs:
                used_diff[d] = False
        return False
